const now = DateTime.now().setZone('Asia/Manila');

const queries = [
  '(OpenAI OR Anthropic OR Gemini OR DeepMind OR "Meta AI" OR Microsoft OR xAI OR Mistral OR DeepSeek) ' +
    '(launch OR release OR update OR benchmark) when:1d',
  '("AI agent" OR "agentic AI" OR "AI assistant" OR "AI automation" OR "AI coding") ' +
    '(launch OR release OR integration OR rollout) when:1d',
  '("AI research" OR "AI breakthrough" OR "open-weight model" OR "AI benchmark") ' +
    '(published OR released OR solves OR outperforms) when:1d',
  '("enterprise AI" OR "AI regulation" OR "AI safety" OR "AI security" OR "AI chips") ' +
    '(adoption OR deployment OR law OR ruling OR breach OR investment) when:1d',
];

return queries.map((query, index) => ({
  json: {
    discovery_date: now.toFormat('yyyy-LL-dd'),
    fetched_at: now.toISO(),
    query,
    query_index: index + 1,
  },
}));

const inputItems = $input.all();
const queryItems = $('02. Build — SerpAPI Queries').all();

function pairedIndex(item, fallback) {
  const paired = item.pairedItem;

  if (Array.isArray(paired)) {
    return Number(paired[0]?.item ?? fallback);
  }

  if (paired && typeof paired === 'object') {
    return Number(paired.item ?? fallback);
  }

  return fallback;
}

function normalizeTitle(value) {
  return String(value || '')
    .normalize('NFKC')
    .trim()
    .replace(/\s+/g, ' ')
    .toLowerCase();
}

function normalizeUrl(value) {
  const raw = String(value || '').trim();

  if (!raw) {
    return '';
  }

  try {
    const url = new URL(raw);

    url.hash = '';
    url.hostname = url.hostname.toLowerCase();

    const usesDefaultHttpsPort =
      url.protocol === 'https:' && url.port === '443';
    const usesDefaultHttpPort =
      url.protocol === 'http:' && url.port === '80';

    if (usesDefaultHttpsPort || usesDefaultHttpPort) {
      url.port = '';
    }

    const trackingKeys = new Set([
      'gclid',
      'fbclid',
      'dclid',
      'mc_cid',
      'mc_eid',
    ]);

    for (const key of [...url.searchParams.keys()]) {
      const lowerKey = key.toLowerCase();

      if (lowerKey.startsWith('utm_') || trackingKeys.has(lowerKey)) {
        url.searchParams.delete(key);
      }
    }

    url.searchParams.sort();

    if (url.pathname.length > 1) {
      url.pathname = url.pathname.replace(/\/+$/, '');
    }

    return url.toString();
  } catch {
    return raw.replace(/#.*$/, '').replace(/\/+$/, '');
  }
}

function sourceName(source) {
  if (typeof source === 'string') {
    return source.trim();
  }

  return String(source?.name || source?.title || 'Unknown source').trim();
}

function publicationValue(result) {
  return String(
    result.iso_date ||
      result.published_at ||
      result.published ||
      result.date ||
      '',
  ).trim();
}

function publicationMillis(value) {
  const parsed = Date.parse(value);

  return Number.isFinite(parsed) ? parsed : 0;
}

function flattenNews(results, query, queryIndex) {
  const flattened = [];

  const walk = (entries, inheritedPosition) => {
    if (!Array.isArray(entries)) {
      return;
    }

    entries.forEach((entry, index) => {
      if (!entry || typeof entry !== 'object') {
        return;
      }

      const position = Number(
        entry.position ?? inheritedPosition ?? index + 1,
      );
      const title = String(entry.title || '').trim();
      const url = String(entry.link || entry.url || '').trim();

      if (title || url) {
        const publishedAt = publicationValue(entry);

        flattened.push({
          position: Number.isFinite(position)
            ? position
            : Number.MAX_SAFE_INTEGER,
          query_index: queryIndex,
          query,
          title,
          source: sourceName(entry.source),
          url,
          published_at: publishedAt,
          published_ms: publicationMillis(publishedAt),
        });
      }

      if (Array.isArray(entry.stories)) {
        walk(entry.stories, position);
      }
    });
  };

  walk(results, undefined);

  return flattened;
}

let successfulQueries = 0;
let failedQueries = 0;
let candidates = [];

inputItems.forEach((item, index) => {
  const data = item.json || {};
  const pairedItemIndex = pairedIndex(item, index);
  const fallbackQuery =
    queryItems[pairedItemIndex]?.json?.query ||
    queryItems[index]?.json?.query ||
    '';
  const query = String(data.search_parameters?.q || fallbackQuery);
  const queryIndex = Number(
    queryItems.find((queryItem) => queryItem.json.query === query)?.json
      ?.query_index ||
      queryItems[pairedItemIndex]?.json?.query_index ||
      index + 1,
  );
  const status = String(data.search_metadata?.status || '').toLowerCase();
  const failed =
    Boolean(data.error) || status === 'error' || status === 'failed';

  if (failed) {
    failedQueries += 1;
    return;
  }

  successfulQueries += 1;
  candidates = candidates.concat(
    flattenNews(data.news_results, query, queryIndex),
  );
});

const configuredQueries = queryItems.length || 4;

failedQueries += Math.max(
  0,
  configuredQueries - successfulQueries - failedQueries,
);

candidates.sort(
  (first, second) =>
    first.position - second.position ||
    first.query_index - second.query_index ||
    second.published_ms - first.published_ms ||
    normalizeTitle(first.title).localeCompare(
      normalizeTitle(second.title),
    ),
);

const seen = new Set();
const unique = [];

for (const candidate of candidates) {
  const normalizedUrl = normalizeUrl(candidate.url);
  const normalizedTitle = normalizeTitle(candidate.title);
  const dedupeKey = normalizedUrl
    ? 'url:' + normalizedUrl
    : 'title:' + normalizedTitle;

  if (!normalizedTitle && !normalizedUrl) {
    continue;
  }

  if (seen.has(dedupeKey)) {
    continue;
  }

  seen.add(dedupeKey);
  unique.push({
    ...candidate,
    normalized_url: normalizedUrl,
    normalized_title: normalizedTitle,
  });
}

const manilaNow = DateTime.now().setZone('Asia/Manila');
const discoveryDate = String(
  queryItems[0]?.json?.discovery_date ||
    manilaNow.toFormat('yyyy-LL-dd'),
);
const fetchedAt = String(
  queryItems[0]?.json?.fetched_at || manilaNow.toISO(),
);
const results = unique.slice(0, 5).map((result, index) => ({
  result_id:
    discoveryDate +
    '|' +
    (result.normalized_url || 'title:' + result.normalized_title),
  discovery_date: discoveryDate,
  fetched_at: fetchedAt,
  rank: index + 1,
  title: result.title || '(Untitled)',
  source: result.source,
  url: result.normalized_url || result.url,
  published_at: result.published_at,
  query: result.query,
}));

return [
  {
    json: {
      discovery_date: discoveryDate,
      fetched_at: fetchedAt,
      successful_query_count: successfulQueries,
      failed_query_count: failedQueries,
      complete_failure: successfulQueries === 0,
      has_results: results.length > 0,
      result_count: results.length,
      results,
      alert_source: successfulQueries === 0 ? 'SerpAPI' : '',
      alert_message:
        successfulQueries === 0
          ? 'All four Google News queries failed after three attempts.'
          : '',
    },
  },
];

const summary = $input.first().json;
const results = Array.isArray(summary.results) ? summary.results : [];

return results.map((result, index) => ({
  json: {
    ...result,
    rank: index + 1,
  },
  pairedItem: {
    item: 0,
  },
}));

const summary = $('04. Select — Top 5 Unique News').first().json;
const results = Array.isArray(summary.results) ? summary.results : [];

const escapeHtml = (value) =>
  String(value || '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const escapeAttribute = (value) =>
  escapeHtml(value).replace(/"/g, '&quot;');

const discoveryToken = String(summary.discovery_date || '')
  .replace(/\D/g, '')
  .slice(0, 8);

if (!/^\d{8}$/.test(discoveryToken)) {
  throw new Error(
    'Discovery date must resolve to YYYYMMDD for Telegram callback data',
  );
}

const lines = [
  '<b>Daily News — ' + escapeHtml(summary.discovery_date) + '</b>',
  '',
];

for (const result of results) {
  const published =
    result.published_at || 'Publication time unavailable';

  lines.push(
    '<b>' + result.rank + '. ' + escapeHtml(result.title) + '</b>',
    escapeHtml(result.source) + ' · ' + escapeHtml(published),
    '<a href="' + escapeAttribute(result.url) + '">Open article</a>',
    '',
  );
}

const telegramKeyboard = {
  rows: results.map((result, index) => {
    const rank = Number(result.rank) || index + 1;
    const callbackData = 'select|' + discoveryToken + '|' + rank;
    const compactTitle = String(result.title || 'Untitled topic')
      .replace(/\s+/g, ' ')
      .trim();
    const titleCharacters = Array.from(compactTitle);
    const shortTitle =
      titleCharacters.length > 36
        ? titleCharacters.slice(0, 36).join('') + '…'
        : compactTitle;

    if (Buffer.byteLength(callbackData, 'utf8') > 64) {
      throw new Error('Telegram callback data exceeds 64 bytes');
    }

    return {
      row: {
        buttons: [
          {
            text: 'Select ' + rank + ' — ' + shortTitle,
            additionalFields: {
              callback_data: callbackData,
            },
          },
        ],
      },
    };
  }),
};

return [
  {
    json: {
      discovery_date: summary.discovery_date,
      result_count: results.length,
      telegram_text: lines.join('\n').trim(),
      telegram_keyboard: telegramKeyboard,
    },
  },
];
